CREATE TABLE IF NOT EXISTS public.fcm_tokens (id uuid NOT NULL DEFAULT gen_random_uuid(), user_id uuid NOT NULL, token text NOT NULL, platform text NOT NULL DEFAULT 'web'::text, user_agent text, last_seen_at timestamp with time zone NOT NULL DEFAULT now(), created_at timestamp with time zone NOT NULL DEFAULT now(), CONSTRAINT fcm_tokens_pkey PRIMARY KEY (id), CONSTRAINT fcm_tokens_token_key UNIQUE (token), CONSTRAINT fcm_tokens_user_id_fkey FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE); ALTER TABLE public.fcm_tokens ENABLE ROW LEVEL SECURITY; DROP POLICY IF EXISTS fcm_tokens_own_all ON public.fcm_tokens; CREATE POLICY fcm_tokens_own_all ON public.fcm_tokens AS PERMISSIVE FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());;
